// Plezy web service worker, generated by scripts/web/build.sh.
//
// Precaches the app shell (the dart2wasm build, the renderer, assets) so the
// installed app starts offline and without refetching ~30 MB per launch. Only
// same-origin GETs are handled; media server traffic always goes to the network.
'use strict';

const BUILD_ID = '__BUILD_ID__';
const PRECACHE = __PRECACHE__;
const CACHE = `plezy-shell-${BUILD_ID}`;
const RUNTIME = `plezy-runtime-${BUILD_ID}`;

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      // Revision-keyed URLs keep an intermediary cache from handing back a
      // previous build's copy of an unchanged path.
      await Promise.all(
        PRECACHE.map(async ([path, revision]) => {
          const response = await fetch(new Request(`${path}?__v=${revision}`, { cache: 'no-cache' }));
          if (!response.ok) throw new Error(`Precache failed for ${path}: ${response.status}`);
          await cache.put(new URL(path, self.registration.scope).href, response);
        }),
      );
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      for (const key of await caches.keys()) {
        if (key.startsWith('plezy-') && key !== CACHE && key !== RUNTIME) await caches.delete(key);
      }
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('message', (event) => {
  if (event.data === 'skipWaiting') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin || request.headers.has('range')) return;
  if (url.pathname.endsWith('/sw.js')) return;

  // Navigations get the shell: it has to match the precached build.
  if (request.mode === 'navigate') {
    event.respondWith(
      (async () => {
        const cached = await caches.match(new URL('index.html', self.registration.scope).href, { cacheName: CACHE });
        return cached || fetch(request);
      })(),
    );
    return;
  }

  event.respondWith(
    (async () => {
      const key = url.origin + url.pathname;
      const cached = (await caches.match(key, { cacheName: CACHE })) || (await caches.match(key, { cacheName: RUNTIME }));
      if (cached) return cached;
      const response = await fetch(request);
      // Lazily loaded files outside the precache (dart2js fallback parts, fonts
      // fetched on demand) are kept for the lifetime of this build.
      if (response.ok && response.type === 'basic') {
        const cache = await caches.open(RUNTIME);
        await cache.put(key, response.clone());
      }
      return response;
    })(),
  );
});
